{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1724;--card:rgba(255,255,255,0.06);--glass:rgba(255,255,255,0.08);--accent:#7dd3fc;--muted:#c7d2fe}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#e6eef8;background:linear-gradient(180deg,#071025 0%,#071833 60%);-webkit-font-smoothing:antialiased}
    header{backdrop-filter:blur(8px);position:sticky;top:0;padding:14px 24px;display:flex;align-items:center;justify-content:space-between}
    .nav{display:flex;gap:12px;align-items:center}
    .nav a{color:var(--muted);text-decoration:none;padding:8px 12px;border-radius:10px;font-weight:600}
    .nav a:hover{background:var(--card);color:#fff}
    .brand{font-weight:700;color:#fff}
    main{max-width:980px;margin:28px auto;padding:20px}
    .hero{display:grid;grid-template-columns:1fr;gap:16px;padding:28px;border-radius:14px;background:linear-gradient(135deg,rgba(255,255,255,0.02),transparent);box-shadow:0 8px 30px rgba(2,6,23,0.6);backdrop-filter: blur(8px)}
    .hero h1{margin:0;color:#fff;font-size:clamp(22px,3vw,32px)}
    .hero p{margin:6px 0 0;color:var(--muted)}
    .row{display:flex;gap:16px;flex-wrap:wrap}
    .card{background:var(--glass);padding:16px;border-radius:12px;box-shadow:inset 0 -1px 0 rgba(255,255,255,0.02)}
    .muted{color:var(--muted);font-size:0.95rem}

    /* Proof gallery */
    .gallery{display:grid;grid-template-columns:2fr 1fr;gap:14px;margin-top:18px}
    .testimonial{padding:18px;border-radius:12px;background:linear-gradient(180deg,rgba(255,255,255,0.03),transparent);min-height:140px;display:flex;flex-direction:column;justify-content:space-between}
    .quote{font-style:italic;color:#eaf6ff}
    .who{font-weight:700;color:#fff;margin-top:12px}
    .badges{display:flex;gap:8px;flex-wrap:wrap}
    .badge{background:rgba(125,211,252,0.12);padding:6px 8px;border-radius:999px;color:var(--accent);font-weight:700;position:relative}
    .badge:hover::after{content:attr(data-tip);position:absolute;left:50%;transform:translateX(-50%);bottom:calc(100% + 8px);background:#051226;color:#dff7ff;padding:8px;border-radius:8px;white-space:nowrap;font-weight:600;font-size:12px}

    /* Path map */
    .path{display:grid;grid-template-columns:1fr;gap:12px;margin-top:18px}
    .controls{display:flex;gap:12px;flex-wrap:wrap}
    .goals{display:flex;flex-direction:column;gap:8px}
    .day-grid{display:flex;gap:6px;flex-wrap:wrap;margin-top:10px}
    .day{width:22px;height:22px;border-radius:6px;background:rgba(255,255,255,0.03);display:flex;align-items:center;justify-content:center;font-size:11px;color:var(--muted);position:relative}
    .day.has{background:linear-gradient(180deg,var(--accent),#60a5fa);color:#04263a}
    .day .dot{width:6px;height:6px;border-radius:50%;background:#04263a}
    .tooltip{position:absolute;left:50%;transform:translateX(-50%);top:calc(100% + 8px);background:#031022;color:#dff7ff;padding:6px 8px;border-radius:8px;font-size:12px;white-space:nowrap;display:none}
    .day:hover .tooltip{display:block}
    .meter{height:10px;border-radius:999px;background:rgba(255,255,255,0.04);overflow:hidden}
    .meter > i{display:block;height:100%;background:linear-gradient(90deg,var(--accent),#60a5fa);width:0}
    .cta{margin-top:18px;padding:16px;text-align:center}
    .primary{background:linear-gradient(90deg,var(--accent),#60a5fa);color:#05212b;padding:10px 14px;border-radius:12px;font-weight:700;border:none;cursor:pointer}
    footer{color:var(--muted);text-align:center;margin:28px 0}
    /* hidden asset reference */
    img.hidden-asset{display:none}
  </style>
</head>
<body>
  <header>
    <div class="brand">{{BUSINESS_NAME}}</div>
    <nav class="nav" aria-label="Primary">
      <a href="index.html">Start</a>
      <a href="about.html">Story</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Courses</a>
      <a href="pricing.html">Plans</a>
      <a href="testimonials.html">Voices</a>
      <a href="book.html">Schedule</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main>
    <section class="hero card">
      <h1>Practical routines for steady wellbeing</h1>
      <p class="muted">Small, intentional shifts that map to your weekly responsibilities. I work with busy people to shape habits that last without adding friction.</p>
      <div style="display:flex;gap:12px;margin-top:12px">
        <a class="primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <a style="background:transparent;color:var(--muted);padding:10px 12px;border-radius:10px;text-decoration:none" href="contact.html">Get in touch</a>
      </div>
    </section>

    <section class="gallery" aria-labelledby="proof-heading">
      <div class="testimonial card" id="testimonial-root">
        <div>
          <div class="quote" id="quote">"Insightful, steady guidance that fit my unpredictable weeks."</div>
          <div class="who" id="who">— A client in {{CITY}}, {{STATE}}</div>
        </div>
        <div style="display:flex;justify-content:space-between;align-items:center;margin-top:12px">
          <div class="badges" id="badges">
            <span class="badge" data-tip="Featured workshop collaborator">Workshop Partner</span>
            <span class="badge" data-tip="Interviewed on local wellness series">Local Guest</span>
            <span class="badge" data-tip="Trusted toolset taught to teams">Team Resource</span>
          </div>
          <div class="muted">Rotating stories · Updated weekly</div>
        </div>
      </div>
      <aside class="card">
        <h3 style="margin-top:0">Credibility & social proof</h3>
        <p class="muted">A rotating selection of voices and simple recognitions that demonstrate outcomes without making medical claims.</p>
        <ul class="muted" style="margin-top:10px;padding-left:16px">
          <li>Member community: ongoing check-ins</li>
          <li>Team workshops for organizations</li>
          <li>Practical frameworks used in daily planning</li>
        </ul>
        <div style="margin-top:12px;text-align:center">
          <button class="primary" onclick="openVoices()">See more voices</button>
        </div>
      </aside>
    </section>

    <section class="path card" aria-labelledby="path-heading">
      <h3 id="path-heading">Design your next 30 days</h3>
      <p class="muted">Select a few goals and view a suggested rhythm mapped across the coming month.</p>
      <div class="controls">
        <div class="goals" id="goal-list">
          <label><input type="checkbox" value="Sleep" /> Short sleep routine</label>
          <label><input type="checkbox" value="Move" /> Brief movement sessions</label>
          <label><input type="checkbox" value="Pause" /> Short daily pause</label>
          <label><input type="checkbox" value="Fuel" /> Simpler eating structure</label>
          <label><input type="checkbox" value="Boundaries" /> Clearer daily boundaries</label>
        </div>
        <div style="flex:1">
          <div class="muted">Preview</div>
          <div class="meter" aria-hidden="true" style="margin-top:8px"><i id="meterBar"></i></div>
          <div style="display:flex;justify-content:space-between;margin-top:8px"><small class="muted">0%</small><small class="muted" id="meterPct">0% planned</small></div>
          <div class="day-grid" id="dayGrid" aria-live="polite" style="margin-top:10px"></div>
        </div>
      </div>
      <div class="cta">
        <button class="primary" id="simulate">Map my month</button>
      </div>
    </section>

    <section class="card" aria-labelledby="benefits">
      <h3 id="benefits">What you can expect</h3>
      <ul class="muted">
        <li>Clear weekly rhythms that slot into busy calendars</li>
        <li>Actionable micro-practices that accumulate into steady results</li>
        <li>Member support and a repeatable framework you can tailor</li>
      </ul>
    </section>

    <section class="card" aria-labelledby="faq">
      <h3 id="faq">Common questions</h3>
      <details class="muted"><summary style="cursor:pointer">How long before I notice a pattern?</summary><div style="margin-top:8px">Most people see a tangible shift in planning and daily ease inside three to five weeks when they follow the suggested rhythm.</div></details>
      <details class="muted"><summary style="cursor:pointer">Is this a medical service?</summary><div style="margin-top:8px">No—this coaching focuses on habits, frameworks, and practical routines, not medical advice.</div></details>
    </section>

    <section class="card cta" style="text-align:center">
      <h4 style="margin:0">Ready to try a simpler structure?</h4>
      <div style="margin-top:10px"><a class="primary" href="{{PRIMARY_CTA_URL}}">Join the membership</a></div>
    </section>

  </main>

  <footer>
    <div>{{BUSINESS_NAME}} • <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    <div style="margin-top:6px" class="muted">Serving {{CITY}}, {{STATE}}</div>
  </footer>

  <!-- hidden reference to asset path required by template system -->
  <img src="assets/img/pattern.svg" class="hidden-asset" alt="decorative pattern" />

  <script>
    // Proof gallery (rotating testimonials + badges with tooltips)
    (function(){
      const items = [
        {quote:'Helped me reclaim small chunks of time that actually made my weeks calmer.', who:'— K., parent and architect, {{CITY}}'},
        {quote:'The routines are forgiving but effective; I can keep them on demanding days.', who:'— M., project manager, {{STATE}}'},
        {quote:'Clear checkpoints and a community for accountability — that changed everything.', who:'— S., designer'}
      ];
      let idx=0;const quoteEl=document.getElementById('quote');const whoEl=document.getElementById('who');const badgesEl=document.getElementById('badges');
      function show(i){const it=items[i];quoteEl.textContent='"'+it.quote+'"';whoEl.textContent=it.who}
      show(0);
      setInterval(()=>{idx=(idx+1)%items.length;show(idx)},4500);
      window.openVoices=function(){location.href='testimonials.html'};
    })();

    // Path map generator
    (function(){
      const grid = document.getElementById('dayGrid');const meterBar=document.getElementById('meterBar');const meterPct=document.getElementById('meterPct');
      function renderEmpty(){grid.innerHTML='';for(let d=1;d<=30;d++){const el=document.createElement('div');el.className='day card';el.textContent=d;grid.appendChild(el)}}
      renderEmpty();
      document.getElementById('simulate').addEventListener('click',()=>{
        const checked=[...document.querySelectorAll('#goal-list input:checked')].map(i=>i.value);
        schedule(checked);
      });
      function schedule(goals){
        // clear
        const days = Array.from({length:30},()=>[]);
        goals.forEach((g,i)=>{
          const sessions=12; // target sessions in 30 days (approx 3/wk)
          const interval = Math.max(2,Math.round(30/sessions));
          for(let s=0;s<sessions;s++){ const day = (i + s*interval) % 30; days[day].push(g); }
        });
        grid.innerHTML='';let daysWith = 0;
        days.forEach((arr,idx)=>{
          const el=document.createElement('div');el.className='day card';el.textContent=idx+1;
          if(arr.length){el.classList.add('has');daysWith++;const tip=document.createElement('div');tip.className='tooltip';tip.textContent=arr.join(' · ');el.appendChild(tip)}
          grid.appendChild(el);
        });
        const pct = Math.round((daysWith/30)*100);
        meterBar.style.width=pct+'%';meterPct.textContent=pct+'% planned';
      }
    })();
  </script>
</body>
</html>"} 
